INSERT INTO public.heritage_items (name, category, city, region, latitude, longitude, description, significance, festival_date, status) VALUES
('Charminar','monument','Hyderabad','Hyderabad',17.3616,78.4747,'Built in 1591 by Muhammad Quli Qutb Shah, the fifth ruler of the Qutb Shahi dynasty, Charminar is Hyderabad''s defining landmark. Its four grand arches and minarets mark the center of the Old City, with a mosque on its upper floor that has been in continuous use for over four centuries. The surrounding lanes host the historic Laad Bazaar and Makkah Masjid, making the area a living hub of commerce and worship rather than just a monument to visit.','Symbol of Hyderabad, officially part of Telangana''s state emblem, and a protected monument under the Archaeological Survey of India.',NULL,'verified'),
('Golconda Fort','monument','Hyderabad','Hyderabad',17.3833,78.4011,'Originally a mud fort built by the Kakatiya dynasty in the 12th century, Golconda was expanded into a massive granite fortress by the Qutb Shahi rulers between the 14th and 17th centuries. It served as the Qutb Shahi capital and a major center of the diamond trade — the Koh-i-Noor is believed to have passed through its markets. The fort is famous for an acoustic system where a handclap at the main gate can be heard nearly a kilometer away at the hilltop pavilion.','Former capital of the Qutb Shahi dynasty and a major diamond trading center of medieval India.',NULL,'verified'),
('Qutb Shahi Tombs','monument','Hyderabad','Hyderabad',17.39,78.3949,'A short distance from Golconda Fort, this garden complex holds the domed granite tombs of seven Qutb Shahi rulers along with family members. It''s one of the few places in the world where an entire ruling dynasty is buried at a single site, with detailed stucco work and colonnades across the mausoleums.','Burial site of the Qutb Shahi dynasty, showcasing Indo-Persian funerary architecture.',NULL,'verified'),
('Chowmahalla Palace','monument','Hyderabad','Hyderabad',17.3583,78.4746,'The former seat of the Asaf Jahi Nizams, built over roughly a century and completed in the mid-19th century, reportedly inspired by the Shah''s Palace in Tehran. Its centerpiece, the Khilwat Mubarak durbar hall, holds nineteen Belgian chandeliers and a vintage 1911 Rolls-Royce among its exhibits.','Official residence and ceremonial hall of the Nizams of Hyderabad State.',NULL,'verified'),
('Ramappa Temple (Kakatiya Rudreshwara Temple)','monument','Palampet','Mulugu district',18.2586,79.941,'Built in 1213 CE under Kakatiya king Ganapati Deva and named after the sculptor who spent 40 years on it, this Shiva temple stands on a star-shaped platform with densely carved pillars, ceilings, and a distinctive lightweight ''floating brick'' tower. It became Telangana''s first UNESCO World Heritage Site in 2021.','UNESCO World Heritage Site (2021); a high point of Kakatiya-era temple architecture and engineering.',NULL,'verified'),
('Thousand Pillar Temple','monument','Hanamkonda','Warangal',18.0069,79.5701,'Constructed by the Kakatiya dynasty in the 12th century, this temple is dedicated jointly to Shiva, Vishnu, and Surya. Locally called Veyi Sthambala Gudi, it''s known for its densely carved pillars, perforated stone screens, and a monolithic Nandi carved from a single block of stone.','One of the finest surviving examples of Kakatiya temple architecture.',NULL,'verified'),
('Bonalu','festival','Hyderabad & Secunderabad','Hyderabad & Secunderabad',17.385,78.4867,'An annual folk festival honoring Goddess Mahakali, believed to trace back to a 19th-century vow made after a plague outbreak. Women carry decorated pots of cooked rice, jaggery, and curd (the ''bonam'') in procession to temples, accompanied by drumming, dance, and a performer called Pothuraju who leads the crowd. Celebrations begin at Golconda Fort and move through temples across the twin cities over about a month.','One of Telangana''s two major women-centered festivals; a state-recognized cultural celebration.','2026-07-19','verified'),
('Bathukamma','festival','Telangana (statewide)','Telangana (statewide)',17.385,78.4867,'A nine-day floral festival where women arrange concentric layers of seasonal, often medicinal, flowers into a temple-shaped stack topped with a turmeric idol of Gauri. The arrangement is worshipped, sung and danced around in circles, and finally immersed in a water body — a ritual tying together earth, water, and community.','Telangana''s official state festival, celebrating the region''s bond with nature and womanhood.','2026-10-11','verified'),
('Pochampally Ikat','craft','Bhoodan Pochampally','Yadadri-Bhuvanagiri district',17.3667,78.9833,'A resist-dye weaving technique where yarns are tied and dyed in patterns before weaving, producing the characteristic soft-edged geometric motifs seen in Pochampally sarees. The craft spread to the region from Chirala and grew into a major cluster of roughly 80 villages and thousands of weaving families. It was the first Indian textile to receive a Geographical Indication tag.','GI-tagged textile tradition; one of India''s best-known handloom techniques.',NULL,'verified'),
('Nirmal Paintings & Toys','craft','Nirmal','Nirmal district',19.0968,78.3441,'Two linked craft traditions from Nirmal town: lightweight wooden toys carved from ''poniki'' wood and painted with natural dyes, and miniature-style Nirmal paintings on wood panels that often use gold foil. Both trace back to patronage under the Kakatiya dynasty and were later promoted as luxury art by the Nizams of Hyderabad.','GI-tagged crafts (toys: 2007, paintings: 2008); supports over 1,000 artisan families today.',NULL,'verified'),
('Red Fort (Lal Qila)','monument','Delhi','Delhi',28.6562,77.241,'Built between 1638 and 1648 by Mughal emperor Shah Jahan as the fortified palace of his new capital, Shahjahanabad, the Red Fort takes its name from the massive red sandstone walls that stretch for over two kilometers. Inside, the Diwan-i-Aam and Diwan-i-Khas halls once housed the legendary Peacock Throne, and Mughal engineers channeled a canal called the Nahr-i-Behisht (''Stream of Paradise'') through the private apartments. Every Independence Day, the Prime Minister of India raises the national flag and addresses the nation from its ramparts.','UNESCO World Heritage Site (2007); site of India''s annual Independence Day flag-hoisting ceremony.',NULL,'verified'),
('Qutub Minar','monument','Delhi','Delhi',28.5245,77.1855,'Construction of this 73-meter tapering sandstone and marble minaret began around 1192 under Qutb al-Din Aibak, the first Sultan of Delhi, and was completed by his successors over the following decades. Its five distinct storeys are ringed with intricately carved verses from the Quran, and the surrounding complex includes the Quwwat-ul-Islam Mosque and the Iron Pillar of Delhi, whose rust-resistant composition has puzzled metallurgists for centuries.','UNESCO World Heritage Site (1993); tallest brick minaret in the world and an early landmark of Indo-Islamic architecture.',NULL,'verified'),
('Humayun''s Tomb','monument','Delhi','Delhi',28.5933,77.2507,'Commissioned in 1565 by Empress Bega Begum for her late husband, Emperor Humayun, this garden tomb was the first of its kind in India, set within a formal charbagh (four-quadrant) Persian garden with water channels running through it. Its double dome and symmetrical red sandstone and white marble facade are widely seen as the architectural template later refined in the Taj Mahal.','UNESCO World Heritage Site (1993); direct architectural precursor to the Taj Mahal.',NULL,'verified'),
('Jama Masjid','monument','Delhi','Delhi',28.6507,77.2334,'Commissioned by Shah Jahan and completed in 1656, Jama Masjid is one of the largest mosques in India, built on a raised platform in Old Delhi with a courtyard that can hold tens of thousands of worshippers. Its three bulbous marble domes and twin 40-meter minarets, built from alternating bands of red sandstone and white marble, overlook the bustling lanes of Chandni Chowk below.','One of the largest and most active mosques in India, commissioned by the same emperor who built the Taj Mahal.',NULL,'verified'),
('Phool Walon Ki Sair','festival','Mehrauli','Delhi',28.5245,77.1855,'A festival of flower-sellers dating to 1812, begun as a vow by the Mughal queen Mumtaz Mahal Begum after her son''s return from exile. Held in Mehrauli after the monsoon, it centers on a procession carrying floral pankhas (fans) that are offered jointly at the Sufi shrine of Khwaja Bakhtiyar Kaki and the nearby Hindu Yogmaya Temple, making it a longstanding symbol of Delhi''s shared Hindu-Muslim heritage. Cultural performances are held at the Mughal-era Jahaz Mahal, and the sitting Prime Minister has served as patron since the festival''s 1962 revival.','A three-day interfaith festival celebrating Delhi''s Ganga-Jamuni (composite Hindu-Muslim) culture.','2026-03-15','verified'),
('Delhi Meenakari & Zardozi','craft','Old Delhi / Chandni Chowk','Old Delhi / Chandni Chowk',28.6507,77.2334,'Two allied court crafts long practiced in the lanes around Chandni Chowk: meenakari, the enameling of gold and silver with vivid fired colors, and zardozi, metal-thread embroidery using gold and silver wire, sequins, and beads to embellish fabric. Both trace back to Mughal royal workshops and were sustained after the empire''s decline by artisan families who supplied jewelry and ceremonial garments to Delhi''s elite.','Mughal court crafts still practiced by hereditary artisan families in Old Delhi.',NULL,'verified'),
('Taj Mahal','monument','Agra','Agra',27.1751,78.0421,'Commissioned in 1632 by Mughal emperor Shah Jahan as a mausoleum for his wife Mumtaz Mahal, the Taj Mahal took roughly two decades and thousands of artisans to complete. Its white marble dome and minarets sit on a raised plinth beside the Yamuna River, flanked by a mosque and guesthouse in red sandstone, with pietra dura inlay of semi-precious stones across its surfaces.','UNESCO World Heritage Site (1983); one of the most recognised buildings in the world.',NULL,'verified'),
('Agra Fort','monument','Agra','Agra',27.1795,78.0211,'A red sandstone fortress rebuilt by Emperor Akbar starting in 1565 on the site of an earlier fort, later embellished with white marble palaces by his grandson Shah Jahan. It served as the principal residence of Mughal emperors until the capital shifted to Delhi, and it was here that Shah Jahan spent his final years under house arrest, reportedly gazing at the Taj Mahal from the Musamman Burj tower.','UNESCO World Heritage Site (1983); Mughal imperial capital before Shahjahanabad.',NULL,'verified'),
('Fatehpur Sikri','monument','Fatehpur Sikri','Agra district',27.0937,77.671,'Built by Emperor Akbar starting in 1571 as a planned capital city honoring the Sufi saint Salim Chishti, whose blessing Akbar credited for the birth of his son. The red sandstone complex of palaces, courts, and the vast Jama Masjid was abandoned within about 15 years, likely due to water shortages, leaving it remarkably preserved as a single-period snapshot of Mughal urban planning.','UNESCO World Heritage Site (1986); a short-lived but architecturally complete Mughal capital.',NULL,'verified'),
('Taj Mahotsav','festival','Agra','Agra',27.1751,78.0421,'An annual ten-day cultural fair held near the Taj Mahal since 1992, organized by Uttar Pradesh Tourism to give craftspeople from across India a direct platform to sell traditional handicrafts without the markups of retail. Alongside stalls of woodwork, textiles, and pottery, the festival features folk dance, music, and regional cuisine, drawing both domestic and international visitors during Agra''s cooler winter season.','One of North India''s largest annual craft and cultural fairs, marking its 35th edition in 2026.','2026-02-18','verified'),
('Agra Marble Inlay (Pietra Dura)','craft','Agra','Agra',27.1751,78.0421,'A stone-inlay technique brought to Agra by Mughal craftsmen and immortalized in the Taj Mahal''s marble surfaces, where thin slices of semi-precious stone such as lapis lazuli, carnelian, and malachite are cut and set into white marble to form floral patterns. Descendants of the original artisans still practice the craft in Agra workshops, producing tabletops, coasters, and decorative panels using the same hand-cutting methods.','Living continuation of the inlay artistry used on the Taj Mahal itself.',NULL,'verified'),
('Hawa Mahal','monument','Jaipur','Jaipur',26.9239,75.8267,'Built in 1799 by Maharaja Sawai Pratap Singh, this five-story pink sandstone facade was designed so the women of the royal household could observe street life and processions through 953 small latticed windows (jharokhas) without being seen themselves. Shaped like the crown of Krishna, its honeycomb structure also allows air to circulate through the building, giving it the name ''Palace of Winds''.','Iconic symbol of Jaipur and an example of Rajput screen architecture.',NULL,'verified'),
('Amer Fort','monument','Amer','Jaipur district',26.9855,75.8513,'Built starting in 1592 by Raja Man Singh I on the ruins of an earlier fort, Amer Fort combines Rajput and Mughal architectural styles across a series of courtyards, including the mirror-inlaid Sheesh Mahal and the Sukh Niwas cooled by a water cascade. Overlooking Maota Lake, it served as the seat of the Kachwaha Rajput rulers before the capital moved to Jaipur city.','UNESCO World Heritage Site (2013, part of the Hill Forts of Rajasthan); former Kachwaha Rajput capital.',NULL,'verified'),
('City Palace, Jaipur','monument','Jaipur','Jaipur',26.9258,75.8237,'Founded by Maharaja Sawai Jai Singh II alongside the planned city of Jaipur in 1727, the City Palace complex blends Rajput, Mughal, and European architectural elements across its courtyards, gates, and gardens. It remains the residence of the former royal family, with sections open as a museum displaying royal costumes, weaponry, and a pair of the world''s largest silver vessels.','Seat of the Kachwaha dynasty and still partly a royal residence.',NULL,'verified'),
('Jantar Mantar, Jaipur','monument','Jaipur','Jaipur',26.9246,75.8247,'An astronomical observatory built between 1728 and 1734 by Maharaja Sawai Jai Singh II, an avid astronomer, featuring nineteen large masonry instruments designed to track celestial bodies and measure time with striking precision. Its centerpiece, the Vrihat Samrat Yantra, is the world''s largest stone sundial, accurate to within about two seconds.','UNESCO World Heritage Site (2010); largest and best-preserved of Jai Singh II''s five observatories.',NULL,'verified'),
('Gangaur','festival','Jaipur & Rajasthan (statewide)','Jaipur & Rajasthan (statewide)',26.9239,75.8267,'An 18-day festival beginning at Holi and dedicated to Gauri (Parvati) and Shiva, observed mainly by married women praying for their husbands'' long lives and by unmarried women seeking a good match. Clay idols of Gauri and Isar are dressed, worshipped daily, and finally carried in an elaborate procession through Jaipur''s Old City to be immersed, accompanied by folk songs, dancing, and women dressed in traditional Rajasthani finery.','Rajasthan''s major women-centered festival, celebrated most prominently in Jaipur and Udaipur.','2026-03-21','verified'),
('Jaipur Blue Pottery','craft','Jaipur','Jaipur',26.9239,75.8267,'A distinctive glazed pottery made without clay, using a dough of quartz stone powder, powdered glass, and Multani mitti, fired and finished with a signature cobalt-blue and white glaze. Introduced to Jaipur under the patronage of Maharaja Sawai Ram Singh II in the 19th century after the technique arrived from Persia via the Mughals, it is now used for tiles, vases, and tableware.','GI-tagged craft closely associated with Jaipur''s royal patronage history.',NULL,'verified'),
('Bandhani (Rajasthani Tie-Dye)','craft','Jaipur & Rajasthan','Jaipur & Rajasthan',26.9239,75.8267,'A resist-dye technique in which fabric is pinched and tied into thousands of tiny knots before dyeing, producing dotted patterns once the knots are untied to reveal the undyed fabric beneath. Practiced across Rajasthan and Gujarat for centuries, Bandhani odhnis and sarees are closely tied to Rajasthani wedding and festival dress, including the Gangaur celebrations.','GI-tagged textile craft central to Rajasthani festive and bridal wear.',NULL,'verified'),
('Jaipur Kundan-Meenakari Jewellery','craft','Jaipur','Jaipur',26.9258,75.8237,'A jewelry-making tradition combining kundan, the setting of gemstones in refined gold using lac as an adhesive, with meenakari enamel work often applied to the reverse of the same piece. Brought to Jaipur by artisans invited from Bengal and Lahore under royal patronage in the 18th century, the craft is still concentrated in Jaipur''s Johari Bazaar workshops.','Signature royal jewelry craft of Jaipur, historically patronized by the Kachwaha court.',NULL,'verified');